<?php
declare(strict_types=1);
session_start();
if (file_exists(__DIR__.'/config.php')) { http_response_code(403); exit('نصب قبلاً انجام شده است. برای امنیت، فایل install.php را از هاست حذف کنید.'); }
$error=''; $done=false;
if ($_SERVER['REQUEST_METHOD']==='POST') {
  $host=trim($_POST['db_host']??'localhost'); $name=trim($_POST['db_name']??''); $user=trim($_POST['db_user']??''); $pass=(string)($_POST['db_pass']??'');
  $admin=trim($_POST['admin_user']??''); $apass=(string)($_POST['admin_pass']??'');
  if (!$name||!$user||strlen($admin)<4||strlen($apass)<12) $error='نام پایگاه داده، نام کاربری دیتابیس و نام مدیر الزامی است. رمز مدیر باید حداقل ۱۲ کاراکتر باشد.';
  else try {
    $pdo=new PDO("mysql:host={$host};dbname={$name};charset=utf8mb4",$user,$pass,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);
    $sql=file_get_contents(__DIR__.'/schema.sql'); foreach(array_filter(array_map('trim',explode(';',$sql))) as $stmt) $pdo->exec($stmt);
    $pdo->prepare('INSERT INTO admins(username,password_hash) VALUES(?,?)')->execute([$admin,password_hash($apass,PASSWORD_DEFAULT)]);
    foreach(['گیاهان دارویی','فرآورده گیاهی','مراقبت و سلامت','دمنوش'] as $cn){$slug='cat-'.bin2hex(random_bytes(5));$pdo->prepare('INSERT IGNORE INTO categories(name,slug) VALUES(?,?)')->execute([$cn,$slug]);}
    if((int)$pdo->query('SELECT COUNT(*) FROM products')->fetchColumn()===0){$seed=[['اسطوخودوس ایرانی','گیاهان دارویی','اسطوخودوس ایرانی؛ تصویر محصول نمونه. مشخصات و توضیحات نهایی را از پنل مدیریت ویرایش کنید.',240000,0,'assets/lavender-product.jpg'],['ترکیب گیاهی شماره یک','فرآورده گیاهی','محصول نمونه؛ پیش از فروش مشخصات واقعی و تأییدشده را وارد کنید.',380000,0,null],['فرآورده طبیعی ویژه','مراقبت و سلامت','محصول نمونه؛ پیش از فروش مشخصات واقعی و تأییدشده را وارد کنید.',420000,0,null],['محصول گیاهی منتخب','فرآورده گیاهی','محصول نمونه؛ پیش از فروش مشخصات واقعی و تأییدشده را وارد کنید.',310000,0,null]];$ins=$pdo->prepare('INSERT INTO products(name,category_id,description,price,stock,image,active) VALUES(?,?,?,?,?,?,1)');foreach($seed as $x){$q=$pdo->prepare('SELECT id FROM categories WHERE name=?');$q->execute([$x[1]]);$cid=$q->fetchColumn();$ins->execute([$x[0],$cid,$x[2],$x[3],$x[4],$x[5]]);}}
    $cfg="<?php\nreturn ".var_export(['db_host'=>$host,'db_name'=>$name,'db_user'=>$user,'db_pass'=>$pass,'timezone'=>'Asia/Tehran'],true).";\n";
    if(file_put_contents(__DIR__.'/config.php',$cfg,LOCK_EX)===false) throw new RuntimeException('امکان ساخت config.php وجود ندارد. مجوز نوشتن پوشه را بررسی کنید.');
    @chmod(__DIR__.'/config.php',0640); $done=true;
  } catch(Throwable $e){$error='نصب انجام نشد: '.htmlspecialchars($e->getMessage(),ENT_QUOTES,'UTF-8');}
}
?><!doctype html><html lang="fa" dir="rtl"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>نصب پنل مدیریت</title><style>body{font-family:Tahoma,Arial;background:#eef2ed;margin:0;padding:24px;color:#203a32}.box{max-width:620px;margin:5vh auto;background:white;border:1px solid #dce6da;border-radius:22px;padding:28px;box-shadow:0 20px 60px #203a3215}h1{font-size:23px}p{line-height:2;color:#66756b;font-size:13px}label{display:block;margin:14px 0;font-size:13px}input{display:block;width:100%;box-sizing:border-box;margin-top:7px;padding:13px;border:1px solid #dce5da;border-radius:10px;font:inherit}button{background:#203a32;color:#fff;border:0;border-radius:11px;padding:14px 22px;font:inherit;cursor:pointer}.err{background:#fff0ed;color:#923b32;padding:12px;border-radius:10px}.ok{background:#edf7ec;padding:14px;border-radius:10px}</style><div class="box"><h1>راه‌اندازی پنل مدیریت دکتر مصطفی خویی</h1><p>اطلاعات MySQL را از بخش MySQL Databases در cPanel وارد کنید. رمز مدیر حداقل ۱۲ کاراکتر باشد. این فرم فقط یک‌بار قابل اجراست.</p><?php if($error):?><div class="err"><?=$error?></div><?php endif;?><?php if($done):?><div class="ok">نصب پایگاه داده و حساب مدیر با موفقیت انجام شد. اکنون وارد <a href="admin/">پنل مدیریت</a> شوید و فایل install.php را فوراً از هاست حذف کنید.</div><?php else:?><form method="post"><h3>اتصال پایگاه داده</h3><label>میزبان دیتابیس<input name="db_host" value="localhost" required></label><label>نام دیتابیس<input name="db_name" required></label><label>نام کاربری دیتابیس<input name="db_user" required></label><label>رمز دیتابیس<input name="db_pass" type="password"></label><h3>حساب مدیر پنل</h3><label>نام کاربری مدیر<input name="admin_user" minlength="4" required></label><label>رمز عبور مدیر (حداقل ۱۲ کاراکتر)<input name="admin_pass" type="password" minlength="12" required></label><button>نصب پنل مدیریت</button></form><?php endif;?></div></html>